<style>
*{box-sizing:border-box}body{margin:0;background:#f6f3ec;color:#4a3a2c;font:15px "Microsoft YaHei",sans-serif}
main{width:min(940px,100%);margin:auto;padding:32px}
h1{font-size:24px;margin:0 0 8px}p{line-height:1.7;margin:0;color:#7b6a59}
.comparison{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:26px}
