small{display:block;font-size:12px;color:#897b6b;margin-top:14px}
.samples{display:flex;align-items:end;justify-content:center;gap:26px;padding:20px 0 4px}
.sample{text-align:center}.sample p{font-size:12px;margin-top:9px}
.detail{margin-top:24px;padding:20px 24px;background:#ebe4d7;border-radius:12px}
.detail h2{text-align:left;margin-bottom:0}.note{font-size:12px;margin-top:20px}
@media(max-width:640px){main{padding:20px}.comparison{gap:8px}.comparison article{padding:16px 6px}.comparison .icon{--size:90px}.samples{gap:16px;flex-wrap:wrap}}
